$source.SetOutputValue('SN','LOT-A7');$source.SetOutputValue('Width',[double]12.5);$source.SetOutputValue('ResultCode','OK');$source.ResultCode='OK';$assemblyTool.Parameters.TextAssemblyTemplate='{String}|{Number}';$assemblyTool.Parameters.TextAssemblyNumberFormat='0.0';$main.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($assemblyTool,'S55 UI'))|Out-Null;$parser.Parameters.TextParserMode='Literal';$parser.Parameters.TextParserPattern='|';$parser.Parameters.TextParserFieldIndex=2;$parser.Parameters.TextParserConvertNumber=$true;$main.GetMethod('ExecuteFlowTool',$private).Invoke($window,[object[]]@($parser,'S55 UI'))|Out-Null
